export const THEME = {
  primary: {
    main: '#1E2028',
    light: '#272935',
    dark: '#15161C',
    accent: '#2A2D3A'
  },
  secondary: {
    main: '#6D28D9', // Purple
    light: '#7C3AED',
    dark: '#5B21B6'
  },
  accent: {
    red: '#DC2626',
    green: '#059669',
    blue: '#2563EB',
    gold: '#D97706'
  },
  text: {
    primary: '#FFFFFF',
    secondary: '#94A3B8',
    accent: '#CBD5E1'
  },
  border: {
    light: 'rgba(255, 255, 255, 0.1)',
    medium: 'rgba(255, 255, 255, 0.15)',
    heavy: 'rgba(255, 255, 255, 0.2)'
  },
  shadow: {
    sm: '0 2px 4px rgba(0, 0, 0, 0.3)',
    md: '0 4px 6px rgba(0, 0, 0, 0.4)',
    lg: '0 10px 15px rgba(0, 0, 0, 0.5)'
  },
  gradient: {
    primary: ['#1E2028', '#15161C'],
    secondary: ['#6D28D9', '#5B21B6'],
    accent: ['#2A2D3A', '#1E2028']
  }
};
